"""Interface definitions."""

import abc

from jsilib import _utils
from jsilib.aio.interface import IStreamReader
from jsilib.base import IClosable

__all__ = export = _utils.ExportList()


@export
class IJSIMessage(IStreamReader, IClosable):
    """Represents a JSI protocol binary message."""

    def __repr__(self) -> str:
        return f"{self.__class__.__qualname__}(size={self.size()!r})"

    @abc.abstractmethod
    def size(self) -> int:
        """The size of this message (in bytes)."""

    @abc.abstractmethod
    def bytes_left(self) -> int:
        """Number of bytes left for reading (in bytes)."""


@export
class IJSICachedMessage(IClosable):
    """Represents a cached JSI message.

    Cached JSI message can be read several times, and simultaneously by several
    readers. Once :meth:`close` is called on this object, underlying cache is
    destroyed.
    """

    @abc.abstractmethod
    async def acquire(self) -> IJSIMessage:
        """Acquire accessor to a cache content.

        The accessor is returned as :class:`IJSIMessage` object. If this method
        is called on a closed cache, then :exc:`MessageCacheClosedError` is
        raised.
        """


@export
class IJSIConnection(IClosable):
    """Represents connection between two peers over the JSI protocol."""

    @abc.abstractmethod
    async def send(self, message: IJSIMessage):
        """Send message to the remote peer.

        This method awaits for a message to be completely sent. In order to
        send several messages simultaneously over a single connection, you have
        to run async subtasks to do so. Outgoing transfers can only be terminated
        if remote peer calls :meth:`IPayload.close` on a received message
        before receiving it completely.

        :param payload:
            Binary payload to be sent to the remote peer
        """

    @abc.abstractmethod
    async def recv(self) -> IJSIMessage:
        """Await for a next message from the remote peer."""


@export
class IJSIAcceptor(IClosable):
    """Interface for the JSI layer server-side connection factories."""

    @abc.abstractmethod
    async def accept(self) -> IJSIConnection:
        """Await for a new incoming connection."""
